-- 152_replace_decision_268_2023_fintech_startups_non_bank_finance_licensing_rules_single_article_with_preamble_and_six_articles.sql
--
-- إعادة هيكلة قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (268) لسنة 2023 بتاريخ 2023/11/29 بشأن قواعد وإجراءات التأسيس والترخيص للشركات الناشئة
-- فى التكنولوجيا المالية لمزاولة أنشطة التمويل غير المصرفى (منشور بالوقائع المصرية العدد 2 تابع (أ) فى 2 يناير 2024).
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية P2 - المجموعة أ) =====
-- مخزَّن بالهجرة 014 كمادة واحدة (article_no = 1، 9064 حرفاً) تحوى القرار كله (الديباجة والمواد الست والتوقيع) بلا ديباجة مستقلة ولا مواد، فلا يمكن الاستشهاد
-- بمادة أو بند بعينه. والمتن ملوَّث:
--   * ترويسات صفحات الوقائع وأرقام الصفحات (29-35) وبيانات الغلاف (الهيئة العامة للرقابة المالية / قرار رقم ٢٦٨ لسنة ٢٠٢٣ / مجلس إدارة الهيئة...) داخل المتن؛
--   * أرقام هندية، وتاريخ الجلسة والقرار مقلوب الترتيب ("29/11/2023" بدل 2023/11/29 فى العنوان)؛
--   * تنوين منفصل ("تنفيذ ًا" و"وفق ًا" و"وفق ً ا" و"تبع ا" و"معتمد ا" و"أيـ ا") وحروف مفصولة بمسافات ("العقار ى" و"نشاط ى" و"ف ى" و"الت ى" و"الرقم ى" و"المصرف ى"
--     و"الما لية" و"ا لملكية" و"ط لبات" و"إ ليها" و"اخ تصاصات" و"وأن ظمة" و"حاص لا" و"مناس ب")؛
--   * الأقواس مقلوبة فى موضعين ("(5 حتى 1)" بدل "(1 حتى 5)" فى المادة 3، وبند الإحالة فى المادة 2)، والمصطلحان الإنجليزيان مقلوبان ("CYK-E" و"tcartnoC latigiD" و"sIPA")
--     بدل (E-KYC) و(Digital Contract) و(APIs)، والنسبة "(%25)" بدل (25%).
-- وفوق ذلك يمتنع الاستشهاد بمادة بعينها لأن القرار كله مادة واحدة.
--
-- ===== المصدر والمنهجية =====
-- PDF الوقائع المصرية (7 صفحات، ص 29-35 من العدد 2 تابع (أ)، قدّمه صاحب المشروع، وله طبقة نصية). قوبلت الطبقة النصية بصور الصفحات السبع (130 dpi) كلمة بكلمة، وقرئت بصرياً
-- المواضع التى أفسدها ترتيب الاتجاهين فى الطبقة النصية: بند الإحالة "(1، 4، 5، 6، 7، 8، 9)" بالمادة 2، و"(1 حتى 5)" و"(4)" بالمادة 3، و(E-KYC) و(Digital Contract) و(APIs)،
-- و"(25%)" (الصورة: ٢٥٪ بين قوسين)، والتنوين الذى ضاع من الطبقة النصية فى "أيًا" (المادة 2 والمادة 5) و"تبعًا" و"توضيحًا" و"حاليًا" و"معتمدًا" فاستُعيد من الصورة.
-- ثم قوبل النص النهائى بالطبقة النصية: لا فرق فى الألفاظ غير ترويسات الصفحات وترتيب الأرقام والأقواس الناتج عن الاتجاهين. وقوبل بالمخزَّن: لا فرق فى الألفاظ غير الفساد المذكور أعلاه.
-- أُبقى إملاء المصدر (الياء "ى" فى "فى" و"الاستهلاكى" و"المصرفى"، "العقاري" بالياء كما فى المصدر، "الرقمي" فى موضعين بالياء كما فى المصدر، "الالكترونى"، "أية"، "وفقا" بلا تنوين فى
-- المادة 3(4) و3(7) كما فى المصدر، وعبارة "من تاريخ الشركة الناشئة لها" بالمادة 4 كما وردت بلا تصحيح). حُذفت ترويسات الصفحات وأرقامها وبيانات الغلاف وسطر "مجلس إدارة الهيئة العامة للرقابة المالية"،
-- وضُمَّت الحروف المفصولة والتنوين المنفصل، ورُدَّت الأقواس والأرقام إلى صوابها (لاتينية)، وضُبط موضع الفاصلة بحسب الصورة. أُسقطت علامات التشكيل الصغيرة والتطويل وأُبقى تنوين الفتح.
-- التوقيع داخل المادة السادسة. عنوان القرار وعدد الوقائع فى hierarchical_location للديباجة. عنوانا المادتين 2 و3 هما عنوانا القسمين فى المصدر.
--
-- ===== الهيكل =====
-- 7 صفوف، 7 نسخ (version_no = 1): ديباجة (article_no = 0) بتسعة اطلاعات وجلسة المجلس، والمواد 1–6: الأنشطة التى يسرى عليها القرار (6 أنشطة)،
-- شروط وإجراءات التأسيس (6 بنود وطلب التأسيس الرقمى)، شروط الحصول على الترخيص (11 بنداً ومدة الترخيص عامان)، الترخيص النهائى خلال عامين وإلغاء الترخيص،
-- سريان قرار 58/2022 فيما لم يرد به نص وإمساك السجلات، النشر والتوقيع. المفتاح (1، 0) محفوظ فلا تعيد بذرة 014 إدراج المادة القديمة
-- (إدراج laws فيها ON CONFLICT DO NOTHING، وإدراج النسخة مبنى على RETURNING فلا يعمل مع قانون موجود).
--
-- ===== التاريخ =====
-- effective_from = 2024-01-03: المادة السادسة "يعمل به من اليوم التالى لتاريخ نشره فى الوقائع المصرية"، والنشر فى العدد 2 تابع (أ) بتاريخ 2024/1/2 (ثابت برأس كل صفحة من المصدر).
-- لا تُمس بيانات laws.
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (7 صفوف بديباجة سليمة والمادة 6 موجودة)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند
-- أى انحراف (عدد، تنوين منفصل أو حروف مفصولة أو ترويسة، محتوى المواد، إجمالى الطول 7841 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.

BEGIN;
DO $fix152$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 268 AND law_year = 2023 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[152] القرار 268/2023 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 7
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[152] القرار 268/2023 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[152] أُزيلت % مادة من القرار 268/2023 (القرار كله فى مادة واحدة بترويسات صفحات وأرقام هندية وتنوين منفصل وحروف مفصولة)', v_n;
  END IF;
END
$fix152$;

WITH ins0_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم 268 لسنة 2023 بتاريخ 2023/11/29 (منشور بالوقائع المصرية العدد 2 تابع (أ) فى 2024/1/2) بشأن قواعد وإجراءات التأسيس والترخيص للشركات الناشئة فى التكنولوجيا المالية لمزاولة أنشطة التمويل غير المصرفى$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على قانون التمويل العقارى الصادر بالقانون رقم 148 لسنة 2001 والقرارات الصادرة تنفيذًا له ؛
وعلى قانون مكافحة غسل الأموال الصادر بالقانون رقم 80 لسنة 2002 والقرارات الصادرة تنفيذًا له ؛
وعلى القانون رقم 10 لسنة 2009 بتنظيم الرقابة على الأسواق والأدوات المالية غير المصرفية ؛
وعلى القانون رقم 141 لسنة 2014 بتنظيم مزاولة نشاط تمويل المشروعات المتوسطة والصغيرة ومتناهية الصغر والقرارات الصادرة تنفيذًا له ؛
وعلى قانون تنظيم نشاطى التأجير التمويلى والتخصيم الصادر بالقانون رقم 176 لسنة 2018 والقرارات الصادرة تنفيذًا له ؛
وعلى قانون تنظيم استخدام وسائل الدفع غير النقدى الصادر بالقانون رقم 18 لسنة 2019 ؛
وعلى قانون تنظيم نشاط التمويل الاستهلاكى الصادر بالقانون رقم 18 لسنة 2020 والقرارات الصادرة تنفيذًا له ؛
وعلى قانون تنظيم وتنمية استخدام التكنولوجيا المالية فى الأنشطة المالية غير المصرفية الصادر بالقانون رقم 5 لسنة 2022 والقرارات الصادرة تنفيذًا له ؛
وعلى قرار مجلس إدارة الهيئة رقم 58 لسنة 2022 بشأن الشروط والإجراءات المتطلبة للتأسيس والترخيص والموافقة للشركات والجهات الراغبة فى مزاولة الأنشطة المالية غير المصرفية من خلال تقنيات التكنولوجيا المالية ؛
وبعد موافقة مجلس إدارة الهيئة بجلسته المنعقدة بتاريخ 2023/11/29 ؛
قرر :$b0_0$
  FROM laws WHERE law_no = 268 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-01-03', 'active' FROM ins0_0;

WITH ins1_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 1, 0, NULL, $t1_0$المادة الأولى$t1_0$, $b1_0$تسرى أحكام هذا القرار على الشركات الناشئة فى التكنولوجيا المالية الراغبة فى الحصول على ترخيص لمزاولة نشاط أو أكثر من أنشطة التمويل غير المصرفى التالية :
1- نشاط التمويل العقاري .
2- نشاط تمويل المشروعات المتوسطة والصغيرة .
3- نشاط تمويل المشروعات متناهية الصغر .
4- نشاط التأجير التمويلى .
5- نشاط التخصيم .
6- نشاط التمويل الاستهلاكى .$b1_0$
  FROM laws WHERE law_no = 268 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-01-03', 'active' FROM ins1_0;

WITH ins2_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 2, 0, NULL, $t2_0$المادة الثانية - شروط وإجراءات تأسيس الشركات الناشئة فى التكنولوجيا المالية الراغبة فى مزاولة النشاط$t2_0$, $b2_0$يشترط لتأسيس الشركات الناشئة فى التكنولوجيا المالية الراغبة فى مزاولة أيًا من أنشطة التمويل غير المصرفى المشار إليها بالمادة الأولى من هذا القرار، توافر الشروط والمتطلبات التالية :
1- أن تتخذ الشركة شكل شركة مساهمة مصرية .
2- أن يقتصر نشاط الشركة على مزاولة نشاط أو أكثر من الأنشطة المشار إليها بالمادة الأولى من هذا القرار .
3- ألا يقل رأس مال الشركة المصدر والمدفوع عن خمسة عشر مليون جنيه مصرى لكل نشاط من أنشطة التمويل الوارد بالمادة الأولى من هذا القرار أو ما يعادلها بالعملات الأجنبية، وحال الرغبة فى مزاولة أكثر من نشاط من الأنشطة المشار إليها فيجب زيادة رأس مال الشركة تبعًا للأنشطة المطلوب مزاولتها، بمراعاة قواعد الجمع بين الأنشطة الصادرة عن الهيئة .
4- إعداد دراسة فنية واقتصادية للشركة تتضمن توضيحًا لنموذج الأعمال الرقمى وتطبيقاته الذى سيتم مزاولة النشاط من خلاله، وعلى الأخص ما يلى :
(أ) نموذج عمل الشركة الرقمى والميزة التنافسية التى تقدمها الشركة من خلاله، والمتضمن اختلاف نموذج العمل عن الشركات والجهات التقليدية التى تمارس النشاط حاليًا فى السوق المصرى .
(ب) مراحل زيادة رأس مال الشركة المصدر والمدفوع بما لا يقل عن الحد الأدنى المطلوب وفقًا لقرارات مجلس إدارة الهيئة المنظمة لكل نشاط .
(ج) خطة الشركة بشأن البنية التحتية للتكنولوجيا وتأمين المعلومات وحوكمتها المستخدمة لإتمام عمليات رقمنة الإجراءات بشكل كامل من خلال؛ التسجيل الرقمى (E-KYC)، والتقييم الائتمانى من خلال نماذج التقييم الرقمى وما يستلزمه من الربط مع إحدى شركات الاستعلام الائتمانى المصرية ، وإجراءات تسجيل الضمانات بشكل رقمي، والتعاقد الرقمى (Digital Contract)، والمدفوعات الرقمية والتحصيل الرقمي، والتعرف على قوائم الممنوعين من التصرف أو التعامل وبالأخص فى مجال مكافحة غسل الأموال وتمويل الإرهاب بشكل رقمى ، وأنظمة العمل بالمكاتب الخلفية المميكنة بالكامل .
5- ألا تقل النسبة المملوكة للمتخصصين فى مجال التكنولوجيا أو التكنولوجيا المالية سواء الأفراد و/أو الكيانات الاعتبارية عن (25%) من رأس مال الشركة، وتعهد المؤسسين بعدم إجراء أى تعديل فى هيكل ملكية الشركة يترتب عليه انخفاض نسبة ملكية المتخصصين المشار إليهم عن (25%) من رأس مال الشركة إلا فى حالة استيفاء متطلبات الحد الأدنى من رأس المال المصدر والمدفوع لكل نشاط وفقًا لقرارات مجلس إدارة الهيئة المنظمة لكل نشاط .
6- أن يكون العضو المنتدب للشركة حاصلاً على مؤهل عال مناسب، وأن تتوافر فيه شروط الخبرة المطلوبة لكل نشاط و/أو اجتيازه الاختبارات التى تحددها الهيئة .
وتقدم طلبات تأسيس الشركات المشار إليها على النموذج الرقمى المعد لهذا الغرض، ومن خلال أحد وكلاء المؤسسين المقيدين لدى الهيئة ممن لديهم هوية رقمية ، وذلك عبر البوابة الإلكترونية المخصصة لذلك أو أية وسيلة أخرى تحددها الهيئة، على أن يتضمن الطلب بالإضافة لما تضمنته الفقرة السابقة البيانات والمستندات المشار إليها بالبنود (1، 4، 5، 6، 7، 8، 9) بالمادة الثانية من قرار مجلس إدارة الهيئة رقم 58 لسنة 2022 المشار إليه .
وتدون طلبات تأسيس الشركات المشار إليها فى السجل المعد بالهيئة لهذا الغرض بأرقام متتابعة وفقًا لتاريخ ورودها، ويكون لكل طلب ملف خاص تودع فيه أوراق التأسيس وكل ما يتعلق بذلك من إجراءات .$b2_0$
  FROM laws WHERE law_no = 268 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-01-03', 'active' FROM ins2_0;

WITH ins3_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 3, 0, NULL, $t3_0$المادة الثالثة - شروط حصول الشركات الناشئة فى التكنولوجيا المالية فى مجال التمويل على ترخيص لمزاولة النشاط$t3_0$, $b3_0$على الشركات الناشئة فى التكنولوجيا المالية الراغبة فى الحصول على ترخيص لمزاولة أنشطة التمويل غير المصرفى المشار إليها بالمادة الأولى من هذا القرار ، تقديم طلب الترخيص على النموذج الرقمى المعد لهذا الغرض مرفقًا به المستندات الدالة على استيفاء الشروط الواردة بالبنود (1 حتى 5) من المادة الرابعة من قرار مجلس إدارة الهيئة رقم 58 لسنة 2022 المشار إليه ، بالإضافة لما يلي :
1- تعهد بالبدء فى ممارسة النشاط الفعلى للشركة خلال شهرين على الأكثر من تاريخ صدور الترخيص .
2- تعهد بالحصول على موافقة الهيئة حال الرغبة فى فتح فروع للشركة وبعد سداد مقابل الخدمات المقرر .
3- تعهد بألا تزيد الرافعة المالية للشركة عن أربعة أمثال صافى حقوق الملكية لحين الحصول على الترخيص النهائى .
4- تعهد بإتمام إجراءات زيادة رأس مال الشركة المصدر والمدفوع وفقا لقرارات مجلس إدارة الهيئة المنظمة لكل نشاط، خلال عامين على الأكثر من تاريخ الحصول على ترخيص الشركة الناشئة فى مجال التكنولوجيا المالية .
5- تعهد من جميع مساهمى الشركة بعدم توزيع أية أرباح على المساهمين قبل استكمال زيادة رأس المال المصدر والمدفوع وفقًا للبند (4) أعلاه والحصول على الترخيص النهائى من الهيئة .
6- تعهد بالالتزام فور الحصول على ترخيص الشركة الناشئة بتوفير بيئة تجريبية وأدوات تكنولوجيا للربط الرقمى وفقًا لمتطلبات الهيئة لتبادل المعلومات أو مؤشرات النشاط ولربط الخدمات من خلال (APIs) .
7- تعهد بالالتزام فور الحصول على ترخيص الشركة الناشئة بإبرام وثيقة تأمين ضد المخاطر الإلكترونية تصدر عن إحدى شركات التأمين المرخص لها من الهيئة، وذلك وفقا للضوابط التى تصدرها الهيئة فى هذا الشأن .
8- تقديم دليل سياسات العمل اللازمة لمزاولة النشاط المطلوب الترخيص به ، بما يتوافق مع متطلبات القانون المنظم له وضوابط الهيئة الصادرة فى هذا الشأن .
9- أن يكون تمويل الشركة معتمدًا بشكل أساسى على شركات أو صناديق رأس مال المخاطر سواء المؤسسة فى الداخل أو المؤسسة فى الخارج شريطة أن تكون هذه الشركات أو الصناديق خاضعة لرقابة جهة تمارس اختصاصات مماثلة لاختصاصات الهيئة أو البنك المركزى المصرى .
10- التعهد بالربط الالكترونى الكامل مع الهيئة قبل بدء مزاولة النشاط .
11- ما يفيد سداد مقابل فحص ودراسة طلب الترخيص بواقع خمسة وعشرون ألف جنيه مصرى ، يسدد بإحدى وسائل الدفع غير النقدى .
ويكون الترخيص الممنوح للشركات الناشئة فى مجال التكنولوجيا المالية لمزاولة أنشطة التمويل غير المصرفى الخاضعة لأحكام هذا القرار لمدة عامين لحين قيامها باستكمال متطلبات الترخيص النهائى .$b3_0$
  FROM laws WHERE law_no = 268 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2024-01-03', 'active' FROM ins3_0;

