DO $verify152$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 268 AND law_year = 2023 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[152] القرار 268/2023 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 7 THEN RAISE EXCEPTION '[152] عدد المواد % بدل 7', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2024-01-03';
  IF v_v <> 7 THEN RAISE EXCEPTION '[152] عدد النسخ % بدل 7', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%الوقائع المصریة%' OR body LIKE '%الوقائع المصرية –%' OR body LIKE '%تابع )%' OR body LIKE '%ینایر%' OR body LIKE '%قرار رقم 268%' OR body LIKE '% ً%' OR body LIKE '%تنفيذ ًا%' OR body LIKE '%العقار ى%' OR body LIKE '%نشاط ى%' OR body LIKE '%التمويل ى%' OR body LIKE '%٢٠٢٣%' OR body LIKE '%سنة 2024
%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[152] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع%' AND body LIKE '%رقم 148 لسنة 2001%' AND body LIKE '%رقم 80 لسنة 2002%' AND body LIKE '%رقم 10 لسنة 2009%' AND body LIKE '%رقم 141 لسنة 2014%' AND body LIKE '%رقم 176 لسنة 2018%' AND body LIKE '%رقم 18 لسنة 2019%' AND body LIKE '%رقم 18 لسنة 2020%' AND body LIKE '%رقم 5 لسنة 2022%' AND body LIKE '%رقم 58 لسنة 2022%' AND body LIKE '%بتاريخ 2023/11/29 ؛%' AND body LIKE '%قرر :') THEN RAISE EXCEPTION '[152] الديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'تسرى أحكام هذا القرار على الشركات الناشئة%' AND body LIKE '%1- نشاط التمويل العقاري .%' AND body LIKE '%6- نشاط التمويل الاستهلاكى .') THEN RAISE EXCEPTION '[152] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'يشترط لتأسيس الشركات الناشئة%' AND body LIKE '%خمسة عشر مليون جنيه مصرى%' AND body LIKE '%(E-KYC)%(Digital Contract)%' AND body LIKE '%عن (25%' AND body LIKE '%6- أن يكون العضو المنتدب%' AND body LIKE '%بالبنود (1، 4، 5، 6، 7، 8، 9) بالمادة الثانية%' AND body LIKE '%من إجراءات .') THEN RAISE EXCEPTION '[152] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'على الشركات الناشئة فى التكنولوجيا المالية الراغبة%' AND body LIKE '%بالبنود (1 حتى 5) من المادة الرابعة%' AND body LIKE '%1- تعهد بالبدء%' AND body LIKE '%4- تعهد بإتمام إجراءات زيادة رأس مال%' AND body LIKE '%(APIs) .%' AND body LIKE '%11- ما يفيد سداد مقابل فحص ودراسة طلب الترخيص بواقع خمسة وعشرون ألف جنيه%' AND body LIKE '%متطلبات الترخيص النهائى .') THEN RAISE EXCEPTION '[152] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'تلتزم الشركات الحاصلة على ترخيص الشركة الناشئة%' AND body LIKE '%خلال مدة لا تجاوز عامين%' AND body LIKE '%ويلغى الترخيص الممنوح%' AND body LIKE '%نشاطها .') THEN RAISE EXCEPTION '[152] المادة 4 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 5 AND article_suffix_order = 0 AND body LIKE 'تسرى على الشركات الحاصلة على ترخيص الشركة الناشئة%' AND body LIKE '%بقرار مجلس إدارة الهيئة رقم 58 لسنة 2022%' AND body LIKE '%وتلتزم الشركات الحاصلة%وفق ما تحدده الهيئة فى هذا الشأن .') THEN RAISE EXCEPTION '[152] المادة 5 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 6 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار فى الوقائع المصرية%' AND body LIKE '%من اليوم التالى لتاريخ نشره فى الوقائع المصرية .%' AND body LIKE '%د/ محمد فريد صالح') THEN RAISE EXCEPTION '[152] المادة 6 غير سليم'; END IF;
  IF v_len <> 7841 THEN RAISE EXCEPTION '[152] إجمالى طول المواد % بدل 7841', v_len; END IF;
  RAISE NOTICE '[152] القرار 268/2023: 7 مواد و7 نسخ، إجمالى % حرف', v_len;
END
$verify152$;

COMMIT;
